from taf.sbts.oam.coam.admin.interfaces.admin_22r1 import SBTS22R1


class SBTS22R2(SBTS22R1):

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS22R2, self).__init__(api_client)

    def get_transport_module_list(self, timeout=60, detailed_output=False):
        """
        Get transport module list.

        :param int timeout: Time to wait for positive procedure result.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getTransportModuleList.html
        """

        result = self._api_client.execute_customer_procedure("getTransportModuleList", {}, timeout)
        return result if detailed_output else result.get(self._provided_content.request_message)

    def get_transport_module_by_id(self, id, timeout=60, detailed_output=False):
        """
        Get transport module by id.

        :param int timeout: Time to wait for positive procedure result.
        :param string id: <TRMOD|TTMOD distName>
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getTransportModuleById.html
        """

        result = self._api_client.execute_customer_procedure("getTransportModuleById", {"id": id}, timeout)
        return result if detailed_output else result.get(self._provided_content.request_message)

    def get_sfp_data(self, timeout=60, detailed_output=False):
        """
        Get sfp data.

        :param int timeout: Time in seconds to wait for positive procedure result.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-sfpData.html
        """

        result = self._api_client.execute_customer_procedure("sfpData", {}, timeout)
        return result if detailed_output else result.get(self._provided_content.request_message)
